llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "The closest analogue, CP-331,684, has a reported human relative bioavailability of 27% from intravenous and oral clinical studies, directly supporting F ≥ 20% for the query despite its polar and ionizable features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Labetalol, which shares the beta-hydroxy secondary amine and an amide/aromatic framework with the query, showed mean systemic bioavailability of 26 ± 3% in healthy volunteers after oral dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Epanolol, a structurally related beta-blocker with an amide and beta-hydroxyamine, had absolute oral bioavailability of only 7.06% in fasted volunteers, providing contradictory low-F evidence; however, its lower similarity and additional phenolic/nitrile groups limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C60"],
      "claim": "Propafenone, another beta-hydroxyamine drug, showed 4.8% oral bioavailability for 150 mg tablets due to extensive presystemic metabolism, but its low similarity and high pharmacokinetic variability weaken transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The higher-similarity human bioavailability data (CP-331,684 27%; labetalol ~26%) support F ≥ 20%, while the low-F analogues (epanolol, propafenone) are less similar and carry structural liabilities such as phenolic, nitrile, or ketone groups not present in the query. The physicochemical prior is mixed, but the more transferable experimental evidence favors high oral bioavailability.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the query molecule.",
    "All analogue Morgan similarities are below 0.35, limiting quantitative transferability.",
    "No direct permeability, efflux, or first-pass metabolism data are available for the query.",
    "Labetalol's bioavailability is close to the 20% threshold, adding some uncertainty.",
    "Propafenone bioavailability is highly variable due to genetic polymorphism, complicating interpretation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

